// Type declarations for the `sui:*` modules whose source is Solid-typed (the
// variant tables and the icon table). They are generated from SUI's own
// sources, so a variant SUI adds or drops changes the mirror's types too;
// test/generated.test.ts fails while the committed copies are stale.
import type { VariantEntry } from "./source.ts";

const GENERATED =
  "// Generated by build/generate.ts from SUI's source. Do not edit.";

/** SUI factory → the mirror file and the props type its variants take. */
export const FACTORY_TYPES: Readonly<
  Record<string, { readonly file: string; readonly props: string }>
> = {
  createButton: { file: "Button.tsx", props: "ButtonDataProps" },
  createStack: { file: "Layout.tsx", props: "StackDataProps" },
  createRow: { file: "Layout.tsx", props: "RowDataProps" },
  createBox: { file: "Layout.tsx", props: "BoxDataProps" },
  createGrid: { file: "Layout.tsx", props: "GridDataProps" },
  createAppHeader: { file: "Layout.tsx", props: "AppHeaderDataProps" },
  createSurface: { file: "Surface.tsx", props: "SurfaceDataProps" },
  createText: { file: "Text.tsx", props: "TextDataProps" },
  createDivider: { file: "Divider.tsx", props: "DividerDataProps" },
  createIcon: { file: "Icon.tsx", props: "IconDataProps" },
  createMarkedSlider: {
    file: "MarkedSlider.tsx",
    props: "MarkedSliderDataProps",
  },
};

const typeOf = (
  factory: string,
): { readonly file: string; readonly props: string } => {
  const found = FACTORY_TYPES[factory];
  if (!found)
    throw new Error(`no React base for ${factory} (add it to FACTORY_TYPES)`);
  return found;
};

/** The .d.ts for `sui:<component>/variants`, written to src/generated/sui/<component>/. */
export const variantDeclarations = (
  entries: readonly VariantEntry[],
): string => {
  const types = entries.map((e) => typeOf(e.factory));
  const imports = [...new Set(types.map((t) => `${t.props}|${t.file}`))]
    .sort()
    .map((key) => {
      const [props, file] = key.split("|");
      return `import type { ${props} } from "../../../${file}";`;
    });
  return [
    GENERATED,
    'import type { ReactElement } from "react";',
    ...imports,
    "",
    ...entries.map(
      (e, i) =>
        `export declare const ${e.name}: (props: ${types[i]?.props}) => ReactElement;`,
    ),
    "",
  ].join("\n");
};

/** The .d.ts for `sui:Icon/paths`. */
export const iconDeclarations = (names: readonly string[]): string =>
  [
    GENERATED,
    `export type IconName = ${names.map((n) => JSON.stringify(n)).join(" | ")};`,
    "export declare const ICON_PATHS: Readonly<",
    "  Record<IconName, { readonly outline: string; readonly solid: string }>",
    ">;",
    "",
  ].join("\n");
